package com.voicetxt.reader;
import android.app.*;import android.content.*;import android.os.*;import java.util.concurrent.atomic.*;
public class PowerPlaybackTest extends Instrumentation {
    void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
    void ui(Runnable task){AtomicReference<Throwable> error=new AtomicReference<>();runOnMainSync(()->{try{task.run();}catch(Throwable e){error.set(e);}});if(error.get()!=null)throw new AssertionError(error.get());}
    void await(java.util.function.BooleanSupplier predicate,String message)throws Exception{long end=SystemClock.elapsedRealtime()+45000;while(SystemClock.elapsedRealtime()<end){AtomicBoolean done=new AtomicBoolean();ui(()->done.set(predicate.getAsBoolean()));if(done.get())return;Thread.sleep(40);}throw new AssertionError(message);}
    void shell(String command)throws Exception{try(java.io.InputStream output=new ParcelFileDescriptor.AutoCloseInputStream(getUiAutomation().executeShellCommand(command))){byte[] bytes=new byte[256];while(output.read(bytes)!=-1){}}Thread.sleep(300);}
    public void onCreate(Bundle b){super.onCreate(b);start();}
    public void onStart(){Bundle result=new Bundle();MainActivity activity=null;boolean passed=false;try{
        activity=(MainActivity)startActivitySync(new Intent(getTargetContext(),MainActivity.class).putExtra("book_id","power_qa").putExtra("book_name","后台节电验证").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final MainActivity a=activity;await(()->a.system.initialized&&a.offlineReady,"voices not ready");
        ui(()->{a.stop();StringBuilder text=new StringBuilder("第一章 后台节电\n");for(int i=0;i<200;i++)text.append("风从窗外吹来，轻轻翻动书页。我们继续阅读，确认锁屏后声音仍然连贯，文字进度不会丢失。\n");a.text=text.toString();a.chapters=MainActivity.parse(a.text);a.position=0;a.chapter=0;a.readingLanguage="";a.loopPlayback=false;a.rate=1.8f;SystemSpeaker.Option voice=null;for(SystemSpeaker.Option option:a.system.options)if(option.engine.contains("hihonor")&&!option.voice.isNetworkConnectionRequired()){voice=option;break;}check(voice!=null,"Honor voice missing");a.systemVoiceKey=voice.key;a.setReadingMode(false);a.showPosition(true);a.highlight(0,1);Object buffer=a.content.getText();a.highlight(1,2);check(buffer==a.content.getText(),"highlight rebuilt entire text buffer");a.startReading();});await(()->a.position>20&&PlaybackService.active!=null,"system playback did not start");shell("input keyevent 3");shell("input keyevent 223");check(!getTargetContext().getSystemService(PowerManager.class).isInteractive(),"screen not off");await(()->!a.readerVisible,"activity did not enter background");
        for(int mode=0;mode<2;mode++){
            if(mode==1){ui(()->{a.stop(false);a.systemVoiceKey="";a.offlineVoice=2015;a.position=0;a.showPosition(true);a.startReading();});await(()->a.position>20,"native playback did not start");}
            Thread.sleep(12000);long computeStart=CpuWork.heldMillis.get(),began=SystemClock.elapsedRealtime();long[] highlights={0},progress={0};int[] previous={0};ui(()->{check(PlaybackService.active!=null&&!PlaybackService.active.wake.isHeld(),"session wake lock held after startup");highlights[0]=a.highlightUpdates;progress[0]=a.progressUpdates;previous[0]=a.position;});
            for(int i=0;i<4;i++){Thread.sleep(8000);ui(()->{check(a.playing,"background playback stopped: "+a.latestStatus);check(a.position>previous[0],"background audio stalled");check(!a.readerVisible,"test unexpectedly returned to foreground");check(a.highlightUpdates==highlights[0]&&a.progressUpdates==progress[0],"hidden UI still refreshing");check(PlaybackService.active!=null&&!PlaybackService.active.wake.isHeld(),"persistent wake lock reacquired");previous[0]=a.position;});Bundle status=new Bundle();status.putString("stage",mode==0?"Honor system voice screen off":"native voice screen off");status.putInt("progressChecks",i+1);sendStatus(1,status);}
            long elapsed=SystemClock.elapsedRealtime()-began,compute=CpuWork.heldMillis.get()-computeStart;result.putLong(mode==0?"systemComputeWakeMs":"nativeComputeWakeMs",compute);result.putLong(mode==0?"systemSampleWindowMs":"nativeSampleWindowMs",elapsed);if(mode==0)check(compute==0,"system reading acquired processing locks");else check(compute<elapsed,"native processing lock held continuously");
        }
        getTargetContext().startService(new Intent(getTargetContext(),PlaybackService.class).setAction(PlaybackService.PAUSE));await(()->!a.playing&&PlaybackService.active!=null&&!PlaybackService.active.foreground&&CpuWork.active.get()==0,"pause leaked service or processing wake lock");shell("input keyevent 224");ui(()->{a.onResume();check(a.canDrawReader(),"foreground UI did not resume");check(a.highlightUpdates>0&&a.progressUpdates>0,"foreground synchronization missing");});result.putString("result","PASS: Honor and native screen-off playback after startup lock expires; zero background text/highlight refreshes; no session-long wake lock; bounded synthesis locks; pause releases resources; in-place highlight buffer; foreground synchronization");passed=true;
    }catch(Throwable e){result.putString("error",android.util.Log.getStackTraceString(e));}finally{try{shell("input keyevent 224");}catch(Exception ignored){}if(activity!=null){final MainActivity a=activity;ui(()->{a.stop();a.finish();});}getTargetContext().getSharedPreferences("reader_power_qa",0).edit().clear().commit();}finish(passed?-1:0,result);}
}
